import { reactive, computed, onMounted } from "vue";
import { createSharedComposable } from "@vueuse/core";
export const kbdKeysMap = {
  meta: "",
  ctrl: "",
  alt: "",
  win: "\u229E",
  command: "\u2318",
  shift: "\u21E7",
  control: "\u2303",
  option: "\u2325",
  enter: "\u21B5",
  delete: "\u2326",
  backspace: "\u232B",
  escape: "Esc",
  tab: "\u21E5",
  capslock: "\u21EA",
  arrowup: "\u2191",
  arrowright: "\u2192",
  arrowdown: "\u2193",
  arrowleft: "\u2190",
  pageup: "\u21DE",
  pagedown: "\u21DF",
  home: "\u2196",
  end: "\u2198"
};
const _useKbd = () => {
  const macOS = computed(() => import.meta.client && navigator && navigator.userAgent && navigator.userAgent.match(/Macintosh;/));
  const kbdKeysSpecificMap = reactive({
    meta: " ",
    alt: " ",
    ctrl: " "
  });
  onMounted(() => {
    kbdKeysSpecificMap.meta = macOS.value ? kbdKeysMap.command : "Ctrl";
    kbdKeysSpecificMap.ctrl = macOS.value ? kbdKeysMap.control : "Ctrl";
    kbdKeysSpecificMap.alt = macOS.value ? kbdKeysMap.option : "Alt";
  });
  function getKbdKey(value) {
    if (!value) {
      return;
    }
    if (["meta", "alt", "ctrl"].includes(value)) {
      return kbdKeysSpecificMap[value];
    }
    return kbdKeysMap[value] || value;
  }
  return {
    macOS,
    getKbdKey
  };
};
export const useKbd = /* @__PURE__ */ createSharedComposable(_useKbd);
const accent = [
  "default",
  "accent",
  "less"
] as const

const size = [
  "sm",
  "md",
  "lg"
] as const

export default {
  "slots": {
    "base": "inline-flex items-center justify-center px-1 rounded-(--ui-border-radius-2xs) font-(--ui-font-weight-normal) font-[family-name:var(--ui-font-family-system-mono)] uppercase border border-(length:--b24ui-border-width) border-(--b24ui-border-color) text-(--b24ui-color) bg-(--b24ui-background)"
  },
  "variants": {
    "accent": {
      "default": "style-outline",
      "accent": "style-outline-accent-1" as typeof accent[number],
      "less": "style-outline-no-accent"
    },
    "size": {
      "sm": "h-[20px] min-w-[20px] text-(length:--ui-font-size-4xs)/(--ui-font-line-height-reset)",
      "md": "h-[24px] min-w-[24px] text-(length:--ui-font-size-md)/(--ui-font-line-height-reset)",
      "lg": "h-[28px] min-w-[28px] text-(length:--ui-font-size-2xl)/(--ui-font-line-height-reset)"
    }
  },
  "defaultVariants": {
    "accent": "less" as typeof accent[number],
    "size": "md" as typeof size[number]
  }
}
<script>
import theme from "#build/b24ui/kbd";
</script>

<script setup>
import { computed } from "vue";
import { Primitive } from "reka-ui";
import { useAppConfig } from "#imports";
import { useKbd } from "../composables/useKbd";
import { useComponentProps } from "../composables/useComponentProps";
import { tv } from "../utils/tv";
const _props = defineProps({
  as: { type: null, required: false, default: "kbd" },
  value: { type: null, required: false },
  accent: { type: null, required: false, default: "default" },
  size: { type: null, required: false },
  class: { type: null, required: false },
  b24ui: { type: Object, required: false }
});
defineSlots();
const props = useComponentProps("kbd", _props);
const { getKbdKey } = useKbd();
const appConfig = useAppConfig();
const b24ui = computed(() => tv({ extend: tv(theme), ...appConfig.b24ui?.kbd || {} })({
  accent: props.accent,
  size: props.size
}));
</script>

<template>
  <Primitive :as="props.as" data-slot="base" :class="b24ui.base({ class: [props.b24ui?.base, props.class] })">
    <slot>
      {{ getKbdKey(props.value) }}
    </slot>
  </Primitive>
</template>
export default {
  "base": "align-text-top"
}
<script>
import theme from "#build/b24ui/prose/kbd";
</script>

<script setup>
import { computed } from "vue";
import { useAppConfig } from "#imports";
import { useComponentProps } from "../../composables/useComponentProps";
import { tv } from "../../utils/tv";
import B24Kbd from "../Kbd.vue";
const _props = defineProps({
  value: { type: String, required: true },
  class: { type: null, required: false },
  b24ui: { type: Object, required: false }
});
const props = useComponentProps("prose.kbd", _props);
const appConfig = useAppConfig();
const b24ui = computed(() => tv({ extend: tv(theme), ...appConfig.b24ui?.prose?.kbd || {} }));
</script>

<template>
  <B24Kbd :value="props.value" :class="b24ui({ class: [props.b24ui?.base, props.class] })" />
</template>
